/// <summary>
/// Выполняет асинхронное действие с повторными попытками при возникновении сетевых ошибок.
/// </summary>
/// <param name="action">Асинхронная функция, возвращающая целое число, которую нужно выполнить.</param>
/// <param name="attempts">Максимальное количество попыток выполнения действия.</param>
/// <returns>Результат выполнения действия (целое число).</returns>
/// <exception cref="InvalidOperationException">Бросается, если все попытки исчерпаны (теоретически недостижимый случай при правильной логике).</exception>
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Цикл для выполнения действия с ограниченным количеством попыток
    for (var i = 0; i < attempts; i++)
    {
        try 
        {
            // Пытаемся выполнить переданное асинхронное действие
            // Если действие успешно завершается, возвращаем его результат
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            // Перехватываем только сетевые ошибки (HttpRequestException)
            // Условие 'when (i < attempts - 1)' гарантирует, что мы не делаем задержку
            // после последней неудачной попытки (чтобы не ждать зря перед броском исключения)

            // Вычисляем экспоненциальную задержку (backoff):
            // 200 мс * 2^i
            // i=0: 200 мс
            // i=1: 400 мс
            // i=2: 800 мс
            // и т.д.
            // Это помогает снизить нагрузку на сервер при временных сбоях
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
        }
    }

    // Если цикл завершился без возврата (все попытки исчерпаны и последняя попытка завершилась ошибкой),
    // бросаем исключение. На практике этот код может быть недостижимым, если catch не позволяет
    // выйти из цикла, но он необходим для компиляции, так как метод должен вернуть значение.
    throw new InvalidOperationException("unreachable");
}
```

### Ключевые моменты:
1. **`Func<Task<int>> action`** — параметр принимает делегат, который возвращает `Task<int>`, что позволяет передавать любую асинхронную функцию, возвращающую целое число.
2. **`catch (HttpRequestException) when (i < attempts - 1)`** — фильтр исключений с условием. Задержка выполняется только если это не последняя попытка.
3. **`200 * Math.Pow(2, i)`** — экспоненциальный backoff: время ожидания увеличивается в 2 раза с каждой попыткой, начиная с 200 мс.
