// Функция worker представляет собой функцию-работник (goroutine),
// которая обрабатывает задачи из канала jobs и отправляет результаты в канал results.
//
// Параметры:
//   - jobs: канал для получения задач (Job) от отправителя.
//   - results: канал для отправки результатов (Result) получателю.
//   - wg: указатель на WaitGroup для корректного завершения всех работников.
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    // defer wg.Done() гарантирует, что счетчик WaitGroup будет уменьшен
    // в самом конце работы функции, независимо от того, как она завершилась
    // (нормально или с ошибкой). Это позволяет main-функции дождаться
    // завершения всех работников.
    defer wg.Done()

    // Цикл for range jobs читает задачи из канала jobs.
    // Цикл автоматически завершится, когда канал jobs будет закрыт
    // и все элементы из него будут прочитаны.
    for j := range jobs {
        // process(j) выполняет основную логику обработки задачи j.
        // Возвращает результат r и возможную ошибку err.
        r, err := process(j)

        // Если при обработке возникла ошибка:
        if err != nil {
            // Логируем ошибку с идентификатором задачи (j.ID) и текстом ошибки.
            // Это помогает отладке и мониторингу.
            log.Printf("job %d: %v", j.ID, err)
            // continue пропускает отправку результата и переходит к следующей задаче.
            // Результат не отправляется, так как обработка не удалась.
            continue
        }

        // Если ошибок нет, отправляем успешный результат r в канал results.
        // Эта операция блокируется, пока получатель не заберет результат,
        // что обеспечивает синхронизацию между работником и получателем.
        results <- r
    }
}
