```typescript
/**
 * Создаёт дебаунс-обёртку для переданной функции.
 *
 * @param fn - Функция, которую нужно обернуть. Принимает любые аргументы и возвращает void.
 * @param ms - Задержка в миллисекундах, после которой функция будет вызвана.
 * @returns Новая функция с той же сигнатурой, что и `fn`, но с отложенным вызовом.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера.
  // Тип ReturnType<typeof setTimeout> гарантирует корректный тип для clearTimeout.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и исходная `fn`.
  return (...args: Parameters<T>) => {
    // Если таймер уже установлен, отменяем предыдущий вызов.
    // Это обеспечивает "дебаунс" — функция сработает только после того,
    // как перестанут приходить новые вызовы в течение `ms` миллисекунд.
    if (t) clearTimeout(t);

    // Устанавливаем новый таймер.
    // Через `ms` миллисекунд будет вызвана исходная функция `fn`
    // с последними переданными аргументами `args`.
    t = setTimeout(() => fn(...args), ms);
  };
}
```

