/// # Возвращаемое значение
/// `HashMap<String, String>`, где ключи приведены к нижнему регистру и обрезаны от пробелов,
/// а значения обрезаны от пробелов.
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    // Разбиваем входную строку по символу ';' на отдельные пары "ключ=значение"
    s.split(';')
        // Для каждой части пытаемся разделить её по первому вхождению '='.
        // Если '=' не найдено, элемент отбрасывается (filter_map возвращает None).
        .filter_map(|p| p.split_once('='))
        // Преобразуем найденные пары (ключ, значение):
        // - ключ: обрезаем пробелы по крам и приводим к нижнему регистру
        // - значение: обрезаем пробелы по крам
        .map(|(k, v)| (k.trim().to_lowercase(), v.trim().to_string()))
        // Собираем все пары в HashMap
        .collect()
}
