import { useData } from './useData'; // Путь к вашему хуку
import { mockFetch } from './mocks'; // Предположим, у вас есть мок для fetch/axios

// Если вы используете axios, можно использовать jest.mock('axios')
// Если fetch — можно использовать msw (Mock Service Worker) или jest.spyOn

it('loads data', async () => {
  // 1. Рендерим хук. Обратите внимание: результат ещё не содержит данных!
  const { result } = renderHook(() => useData('/api/items'));

  // 2. Ждём, пока состояние хука изменится и данные загрузятся.
  //    waitFor будет повторять проверку, пока условие не выполнится или не истечёт таймаут.
  await waitFor(() => {
    // Проверяем, что массив items содержит 3 элемента
    expect(result.current.items).toHaveLength(3);
  });

  // 3. (Опционально) Можно дополнительно проверить содержимое, если нужно
  // expect(result.current.items[0]).toEqual({ id: 1, name: 'Item 1' });
});
```

